# 有限 Decimal 极值合同：精确 float 有理数、哈希和容器键去重；无上下文算术。
from decimal import Decimal
d = Decimal('4.-324')
f = 5e-324
print(d == f, f == d, d <= f, f <= d, hash(d), hash(f))
print(len({d: 'd', f: 'f'}), len({f: 'f', d: 'd'}), len({d, f}))
d = Decimal('-4.-324')
f = -5e-324
print(d == f, f == d, d <= f, f <= d, hash(d), hash(f))
print(len({d: 'd', f: 'f'}), len({f: 'f', d: 'd'}), len({d, f}))
d = Decimal('2.-308')
f = 2.2250738585072014e-308
print(d == f, f == d, d <= f, f <= d, hash(d), hash(f))
print(len({d: 'd', f: 'f'}), len({f: 'f', d: 'd'}), len({d, f}))
d = Decimal('')
f = 1.7976931348623157e+308
print(d == f, f == d, d <= f, f <= d, hash(d), hash(f))
print(len({d: 'd', f: 'f'}), len({f: 'f', d: 'd'}), len({d, f}))
for text in ['-0E-7', '0.000000', '0.0000000', '100E-8', '1000E-9', '123E+1', '-0E+4']:
    d=Decimal(text)
    print(str(d), repr(d), bool(d), hash(d))
for n in [2305843009213693951,2305843009213693952,5316911983139663487003542222693990401,-2305843009213693952,-1]:
    d=Decimal(n)
    print(hash(n),hash(d),len({n,d}))
for d in [Decimal('-0E+999999999'), Decimal('1.00')]:
    i = 1 if d else 0
    b = bool(i)
    f = 1.0 if d else -0.0
    print(len({d,i,b,f}), len({f,b,i,d}), hash(d)==hash(i)==hash(b)==hash(f))
